const studyId = $json.study_id ?? 'study_test_001';
const outputMode = $json.output_mode ?? 'final_insights';
const supabaseUrl = $env.SUPABASE_URL || 'https://SET_SUPABASE_URL';
const supabaseKey = $env.SUPABASE_SERVICE_ROLE_KEY || 'SET_SUPABASE_SERVICE_ROLE_KEY';
const headers = { 'apikey': supabaseKey, 'Authorization': 'Bearer ' + supabaseKey, 'Content-Type': 'application/json' };

const studyRes = await this.helpers.httpRequest({ method: 'GET', url: supabaseUrl + '/rest/v1/BE_studies?study_id=eq.' + encodeURIComponent(studyId) + '&limit=1', headers });
const study = Array.isArray(studyRes) ? studyRes[0] : null;
if (!study) throw new Error('Study not found: ' + studyId);

const detectionsRes = await this.helpers.httpRequest({ method: 'GET', url: supabaseUrl + '/rest/v1/BE_behavior_detections?study_id=eq.' + encodeURIComponent(studyId) + '&order=timestamp.asc&limit=1000', headers });
const detections = Array.isArray(detectionsRes) ? detectionsRes : [];

// Duration label
const durationSeconds = study.duration_seconds ?? 0;
let durationLabel;
if (durationSeconds < 60) { durationLabel = durationSeconds + ' seconds'; }
else if (durationSeconds < 3600) { const m = Math.round(durationSeconds / 60); durationLabel = m + ' minute' + (m === 1 ? '' : 's'); }
else { const h = (durationSeconds / 3600).toFixed(1); durationLabel = h + ' hour' + (h === '1.0' ? '' : 's'); }

const detectionCount = detections.length;

// Build detection log table in code — NOT sent to the model
// Format: one row per behavior per frame
const detectionLogRows = [];
for (const d of detections) {
  const ts = d.timestamp_pt ?? d.timestamp;
  const behaviors = d.detected_behaviors ?? [];
  if (behaviors.length === 0) {
    detectionLogRows.push([ts, '', '', '', d.notes ?? '']);
  } else {
    for (const b of behaviors) {
      detectionLogRows.push([ts, b.name ?? '', b.value ?? 0, b.unit ?? '', d.notes ?? '']);
    }
  }
}

const detectionLogTable = {
  table_id: 'table_detection_log',
  title: 'Detection Log',
  columns: ['timestamp', 'behavior_name', 'value', 'unit', 'notes'],
  rows: detectionLogRows,
};

// Compact detection_summary sent to the model for chart/insight generation
// Uses same structure but keeps full data — model needs all values for accurate charts
const detectionSummary = detections.map(d => ({
  timestamp: d.timestamp_pt ?? d.timestamp,
  detected_behaviors: d.detected_behaviors ?? [],
  notes: d.notes ?? '',
}));

return [{ json: {
  study_id: studyId,
  output_mode: outputMode,
  study_plan: study.study_plan ?? {},
  graph_plan: study.graph_plan ?? {},
  instructions: study.metadata?.instructions ?? '',
  data_context: {
    duration_seconds: durationSeconds,
    duration_label: durationLabel,
    detection_count: detectionCount,
    sampling_note: 'This study captured ' + detectionCount + ' data point' + (detectionCount === 1 ? '' : 's') + ' over ' + durationLabel + '.',
  },
  // Sent to model for chart and insight generation
  detection_summary: detectionSummary,
  // Built in code — merged into final output AFTER model call, never sent to model
  _detection_log_table: detectionLogTable,
} }];

const body = $json;
const errors = [];
let rawText = '';
try { rawText = body.choices[0].message.content; } catch(e) { errors.push('failed_to_extract_content'); }
let cleaned = rawText.trim();
if (cleaned.startsWith('```')) { cleaned = cleaned.replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '').trim(); }
let parsed = {};
try { parsed = JSON.parse(cleaned); } catch(e) { errors.push('json_parse_failed'); }
// tables not required from model anymore — built in code
for (const field of ["study_id","output_mode","dashboard_summary","charts","insights","recommendations"]) {
  if (!(field in parsed)) errors.push('missing_' + field);
}
return [{ json: { raw_ai_output: rawText, parsed_output: parsed, validation_passed: errors.length === 0, validation_errors: errors } }];

