let rawText = '';
try { rawText = $json.choices[0].message.content; } catch(e) {}
let cleaned = rawText.trim();
if (cleaned.startsWith('```')) { cleaned = cleaned.replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '').trim(); }
let parsed = {};
try { parsed = JSON.parse(cleaned); } catch(e) { parsed = {}; }
return [{ json: { parsed_output: parsed, validation_passed: true, validation_errors: [] } }];

const parsed = $json.parsed_output ?? $json;

// Retrieve the detection log table built in Fetch Study Data
let detectionLogTable = null;
try {
  detectionLogTable = $('Fetch Study Data from Supabase').item.json._detection_log_table;
} catch(e) {}

// Merge: model output gets the code-built detection log table injected
const tables = Array.isArray(parsed.tables) ? parsed.tables : [];
if (detectionLogTable) {
  // Remove any partial table the model may have tried to generate, replace with complete one
  const withoutLog = tables.filter(t => t.table_id !== 'table_detection_log');
  parsed.tables = [...withoutLog, detectionLogTable];
} else {
  parsed.tables = tables;
}

return [{ json: parsed }];
